class Solution {
  public int minMoves(String[] matrix) {
    int m = matrix.length, n = matrix[0].length();
    int[][] cells = new int[26][];
    int[] cnt = new int[26];
    for (int i = 0; i < m; i++)
      for (int j = 0; j < n; j++) {
        char c = matrix[i].charAt(j);
        if (c >= 'A' && c <= 'Z') cnt[c - 'A']++;
      }
    for (int c = 0; c < 26; c++) cells[c] = new int[cnt[c]];
    int[] fill = new int[26];
    for (int i = 0; i < m; i++)
      for (int j = 0; j < n; j++) {
        char c = matrix[i].charAt(j);
        if (c >= 'A' && c <= 'Z') cells[c - 'A'][fill[c - 'A']++] = i * n + j;
      }
    int INF = Integer.MAX_VALUE;
    int[] dist = new int[m * n];
    java.util.Arrays.fill(dist, INF);
    boolean[] done = new boolean[m * n], used = new boolean[26];
    java.util.ArrayDeque<Integer> dq = new java.util.ArrayDeque<>();
    dist[0] = 0;
    dq.add(0);
    int[] dx = {1, -1, 0, 0}, dy = {0, 0, 1, -1};
    while (!dq.isEmpty()) {
      int u = dq.pollFirst();
      if (done[u]) continue;
      done[u] = true;
      int x = u / n, y = u % n;
      char c = matrix[x].charAt(y);
      if (c >= 'A' && c <= 'Z' && !used[c - 'A']) {
        used[c - 'A'] = true;
        for (int v : cells[c - 'A']) {
          if (dist[v] > dist[u]) {
            dist[v] = dist[u];
            dq.addFirst(v);
          }
        }
      }
      for (int d = 0; d < 4; d++) {
        int nx = x + dx[d], ny = y + dy[d];
        if (nx < 0 || ny < 0 || nx >= m || ny >= n || matrix[nx].charAt(ny) == '#') continue;
        int v = nx * n + ny;
        if (dist[v] > dist[u] + 1) {
          dist[v] = dist[u] + 1;
          dq.addLast(v);
        }
      }
    }
    return dist[m * n - 1] == INF ? -1 : dist[m * n - 1];
  }
}
